type mockImportWidgetRecord struct {
	name        string
	zone        string
	description string
	labels      map[string]string
}

type mockImportWidgetBehavior struct {
	dropZoneOnImport        bool
	dropDescriptionOnImport bool
}

func newMockImportProviderFactory(behavior mockImportWidgetBehavior) map[string]func() (tfprotov5.ProviderServer, error) {
	var mu sync.Mutex
	store := make(map[string]mockImportWidgetRecord)

	zoneSuppress := func(_, oldVal, newVal string, _ *schema.ResourceData) bool {
		// Suppress self-link vs short-name difference ("projects/p/zones/us-central1-a" vs "us-central1-a").
		lastPart := func(s string) string {
			parts := strings.Split(s, "/")
			return parts[len(parts)-1]
		}
		return oldVal != "" && newVal != "" && lastPart(oldVal) == lastPart(newVal)
	}

	res := &schema.Resource{
		Identity: &schema.ResourceIdentity{
			Version: 1,
			SchemaFunc: func() map[string]*schema.Schema {
				return map[string]*schema.Schema{
					"name": {
						Type:              schema.TypeString,
						RequiredForImport: true,
					},
				}
			},
		},
		Importer: &schema.ResourceImporter{
			StateContext: func(_ context.Context, d *schema.ResourceData, _ any) ([]*schema.ResourceData, error) {
				idData, err := d.Identity()
				if err != nil {
					return nil, err
				}
				name, _ := idData.GetOk("name")
				nameStr, _ := name.(string)
				d.SetId("projects/p/widgets/" + nameStr)
				_ = d.Set("name", nameStr)
				return []*schema.ResourceData{d}, nil
			},
		},
		Schema: map[string]*schema.Schema{
			"name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"zone": {
				Type:             schema.TypeString,
				Optional:         true,
				ForceNew:         true,
				DiffSuppressFunc: zoneSuppress,
			},
			"description": {
				Type:     schema.TypeString,
				Optional: true,
			},
			"password": {
				Type:      schema.TypeString,
				Optional:  true,
				ForceNew:  true,
				Sensitive: true,
			},
			"labels": {
				Type:     schema.TypeMap,
				Optional: true,
				Elem:     &schema.Schema{Type: schema.TypeString},
			},
			"effective_labels": {
				Type:     schema.TypeMap,
				Computed: true,
				Elem:     &schema.Schema{Type: schema.TypeString},
			},
			"create_time": {
				Type:     schema.TypeString,
				Computed: true,
			},
		},
		CustomizeDiff: func(_ context.Context, d *schema.ResourceDiff, _ any) error {
			if raw := d.Get("labels"); raw != nil {
				eff := map[string]any{"goog-terraform-provisioned": "true"}
				for k, v := range raw.(map[string]any) {
					eff[k] = v
				}
				if err := d.SetNew("effective_labels", eff); err != nil {
					return err
				}
			}
			return nil
		},
		Create: func(d *schema.ResourceData, _ any) error {
			name := d.Get("name").(string)
			zone := d.Get("zone").(string)
			if zone != "" && !strings.Contains(zone, "/") {
				zone = "projects/p/zones/" + zone
			}
			labels := map[string]string{"goog-terraform-provisioned": "true"}
			for k, v := range d.Get("labels").(map[string]any) {
				labels[k] = v.(string)
			}
			mu.Lock()
			store[name] = mockImportWidgetRecord{
				name:        name,
				zone:        zone,
				description: d.Get("description").(string),
				labels:      labels,
			}
			mu.Unlock()

			d.SetId("projects/p/widgets/" + name)
			_ = d.Set("zone", zone)
			_ = d.Set("effective_labels", labels)
			_ = d.Set("create_time", "2026-01-01T00:00:00Z")
			if idData, err := d.Identity(); err == nil && idData != nil {
				_ = idData.Set("name", name)
			}
			return nil
		},
		Read: func(d *schema.ResourceData, _ any) error {
			name := d.Get("name").(string)
			if name == "" && strings.HasPrefix(d.Id(), "projects/p/widgets/") {
				name = strings.TrimPrefix(d.Id(), "projects/p/widgets/")
			}
			mu.Lock()
			rec, ok := store[name]
			mu.Unlock()
			if !ok {
				d.SetId("")
				return nil
			}
			isFreshImport := d.Get("create_time").(string) == ""
			_ = d.Set("name", rec.name)
			if !(isFreshImport && behavior.dropZoneOnImport) {
				_ = d.Set("zone", rec.zone)
			}
			if !(isFreshImport && behavior.dropDescriptionOnImport) {
				_ = d.Set("description", rec.description)
			}
			// Mimic tpgresource.SetLabels: only populate configured keys already in state;
			// on fresh import, labels in state is empty while effective_labels has API labels.
			if _, hasLabels := d.GetOk("labels"); !hasLabels {
				_ = d.Set("labels", map[string]any{})
			}
			_ = d.Set("effective_labels", rec.labels)
			_ = d.Set("create_time", "2026-01-01T00:00:00Z")
			// Note: "password" is intentionally never returned by Read (ignore_read).
			if idData, err := d.Identity(); err == nil && idData != nil {
				_ = idData.Set("name", rec.name)
			}
			return nil
		},
		Update: func(d *schema.ResourceData, _ any) error {
			return nil
		},
		Delete: func(d *schema.ResourceData, _ any) error {
			mu.Lock()
			delete(store, d.Get("name").(string))
			mu.Unlock()
			d.SetId("")
			return nil
		},
	}

	p := &schema.Provider{
		ResourcesMap: map[string]*schema.Resource{
			"mock_widget": res,
		},
	}

	return map[string]func() (tfprotov5.ProviderServer, error){
		"mock": func() (tfprotov5.ProviderServer, error) {
			return schema.NewGRPCProviderServer(p), nil
		},
	}
}

func skipIfNoTerraformCLI(t *testing.T) {
	t.Helper()
	if _, err := exec.LookPath("terraform"); err != nil {
		t.Skip("terraform binary not in PATH; skipping live CLI unit test")
	}
}

func TestExpectImportNoReplaceAndOnlyIgnoredDiffs_LiveCLI(t *testing.T) {
	skipIfNoTerraformCLI(t)
	t.Parallel()

	versionChecks := []tfversion.TerraformVersionCheck{
		tfversion.SkipBelow(tfversion.Version1_12_0),
	}

	t.Run("DiffSuppressFunc and labels update passes", func(t *testing.T) {
		t.Parallel()
		const cfg = `
resource "mock_widget" "test" {
  name        = "w-labels"
  zone        = "us-central1-a"
  description = "hello"
  labels = {
    env = "dev"
  }
}
`
		resource.UnitTest(t, resource.TestCase{
			TerraformVersionChecks:   versionChecks,
			ProtoV5ProviderFactories: newMockImportProviderFactory(mockImportWidgetBehavior{}),
			Steps: []resource.TestStep{
				{Config: cfg},
				{
					ResourceName:       "mock_widget.test",
					ImportState:        true,
					ExpectNonEmptyPlan: true,
					ImportStateKind:    resource.ImportBlockWithResourceIdentity,
					ImportPlanChecks: resource.ImportPlanChecks{
						PreApply: []plancheck.PlanCheck{
							ExpectImportNoReplaceAndOnlyIgnoredDiffs("mock_widget.test", "labels"),
						},
					},
				},
			},
		})
	})

	t.Run("ForceNew ignore_read password replacement passes", func(t *testing.T) {
		t.Parallel()
		const cfg = `
resource "mock_widget" "test" {
  name        = "w-password"
  zone        = "us-central1-a"
  description = "with-secret"
  password    = "top-secret"
}
`
		resource.UnitTest(t, resource.TestCase{
			TerraformVersionChecks:   versionChecks,
			ProtoV5ProviderFactories: newMockImportProviderFactory(mockImportWidgetBehavior{}),
			Steps: []resource.TestStep{
				{Config: cfg},
				{
					ResourceName:       "mock_widget.test",
					ImportState:        true,
					ExpectNonEmptyPlan: true,
					ImportStateKind:    resource.ImportBlockWithResourceIdentity,
					ImportPlanChecks: resource.ImportPlanChecks{
						PreApply: []plancheck.PlanCheck{
							ExpectImportNoReplaceAndOnlyIgnoredDiffs("mock_widget.test", "password"),
						},
					},
				},
			},
		})
	})

	t.Run("Unignored ForceNew field dropped on import is caught", func(t *testing.T) {
		t.Parallel()
		const cfg = `
resource "mock_widget" "test" {
  name = "w-broken-zone"
  zone = "us-central1-a"
}
`
		resource.UnitTest(t, resource.TestCase{
			TerraformVersionChecks: versionChecks,
			ProtoV5ProviderFactories: newMockImportProviderFactory(mockImportWidgetBehavior{
				dropZoneOnImport: true,
			}),
			Steps: []resource.TestStep{
				{Config: cfg},
				{
					ResourceName:       "mock_widget.test",
					ImportState:        true,
					ExpectNonEmptyPlan: true,
					ImportStateKind:    resource.ImportBlockWithResourceIdentity,
					ImportPlanChecks: resource.ImportPlanChecks{
						PreApply: []plancheck.PlanCheck{
							ExpectImportNoReplaceAndOnlyIgnoredDiffs("mock_widget.test"),
						},
					},
					ExpectError: regexp.MustCompile(`unexpected replacement plan.*unignored replace_paths \[zone\]`),
				},
			},
		})
	})

	t.Run("Unignored mutable field dropped on import alongside labels update is caught", func(t *testing.T) {
		t.Parallel()
		const cfg = `
resource "mock_widget" "test" {
  name        = "w-broken-desc"
  description = "must-survive-import"
  labels = {
    env = "prod"
  }
}
`
		resource.UnitTest(t, resource.TestCase{
			TerraformVersionChecks: versionChecks,
			ProtoV5ProviderFactories: newMockImportProviderFactory(mockImportWidgetBehavior{
				dropDescriptionOnImport: true,
			}),
			Steps: []resource.TestStep{
				{Config: cfg},
				{
					ResourceName:       "mock_widget.test",
					ImportState:        true,
					ExpectNonEmptyPlan: true,
					ImportStateKind:    resource.ImportBlockWithResourceIdentity,
					ImportPlanChecks: resource.ImportPlanChecks{
						PreApply: []plancheck.PlanCheck{
							ExpectImportNoReplaceAndOnlyIgnoredDiffs("mock_widget.test", "labels"),
						},
					},
					ExpectError: regexp.MustCompile(`unexpected plan diff on non-ignored attribute\(s\):\s+description:`),
				},
			},
		})
	})
}
